record.field:
company = env.company
if company.ms_agenda_configured:
    sync_engine = env['crearis.agenda.sync']
    result = sync_engine.sync_all(company)
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Sync Complete',
            'message': f"Synced: {result.get('event_types', 0)} types, {result.get('events', 0)} events",
            'type': 'success',
            'sticky': False,
        }
    }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Not Configured',
            'message': 'Please configure MS Agenda settings in Company settings first.',
            'type': 'warning',
            'sticky': False,
        }
    }
